// Official U.S. government data for each model, from lib/official-data.json
// (generated by scripts/fetch_official_data.py). Unlike the site's own
// estimates, these figures come straight from the EPA and NHTSA.

import data from "./official-data.json";

export interface EpaConfig {
  name: string;
  engine: string;
  drive: string;
  transmission: string;
  fuel: string;
  mpg: { city: number; highway: number; combined: number } | null;
  mpge?: number;
  rangeMi?: number | null;
  electricRangeMi?: number | null;
  epaId: number;
}

export interface SafetyRating {
  year: number;
  description: string | null;
  overall: string | null;
  frontal: string | null;
  side: string | null;
  rollover: string | null;
  vehicleId: number;
}

export interface Recall {
  campaign: string | null;
  date: string | null;
  component: string;
  summary: string;
}

export interface OfficialData {
  epa: { year: number; configs: EpaConfig[] } | null;
  epaNote?: string;
  safety: SafetyRating | null;
  /** Null when NHTSA's records couldn't be matched, which isn't the same as zero recalls. */
  recalls: { year: number; count: number; items: Recall[] } | null;
}

const OFFICIAL = data.cars as unknown as Record<string, OfficialData>;
export const OFFICIAL_FETCHED_ON = data.sources.fetchedOn;

export function officialFor(id: string): OfficialData | undefined {
  return OFFICIAL[id];
}

/** Overall NHTSA stars as a number, or null if it wasn't rated. */
export function overallStars(id: string): number | null {
  const n = Number(OFFICIAL[id]?.safety?.overall);
  return Number.isFinite(n) && n > 0 ? n : null;
}

/** A short EPA summary, such as "32–35 mpg" or "245–318 mi range". */
export function epaSummary(id: string): string | null {
  const epa = OFFICIAL[id]?.epa;
  if (!epa) return null;
  const range = (values: number[], unit: string) => {
    if (values.length === 0) return null;
    const lo = Math.min(...values);
    const hi = Math.max(...values);
    return `${lo === hi ? lo : `${lo}–${hi}`} ${unit}`;
  };
  return (
    range(epa.configs.flatMap((c) => c.mpg?.combined ?? []), "mpg") ??
    range(epa.configs.flatMap((c) => c.rangeMi ?? []), "mi range")
  );
}

export const fuelEconomyUrl = (epaId: number) => `https://www.fueleconomy.gov/feg/noframes/${epaId}.shtml`;
export const NHTSA_RATINGS_URL = "https://www.nhtsa.gov/ratings";
export const NHTSA_RECALLS_URL = "https://www.nhtsa.gov/recalls";
